style.css:
@-moz-document domain("reddit.com") {
/* 1. FONDO: Color Frambuesa Rosa Bonito con Puntos Blancos */
    body, shreddit-app, #shreddit-grid, main, .grid, div[id^="t3_"], 
    .bg-neutral-background, [style*="background-color"],
    #main-content, shreddit-feed, .subreddits-list {
        background-color: #db335b !important;
        background-image: radial-gradient(#FFFFFF 12%, transparent 12%),
                          radial-gradient(#FFFFFF 12%, transparent 12%) !important;
        background-size: 26px 26px !important;
        background-position: 0 0, 13px 13px !important;
        background-attachment: fixed !important;
    }

    .theme-light, .theme-dark, .bg-neutral-background-weak, matrix-container {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 2. BARRA DE BÚSQUEDA: Se queda en Rosa Pastel o Blanco (¡Incluso al hacer clic!) */
    shreddit-search-id, 
    form[action="/search"], 
    input[type="search"],
    shreddit-search-id:focus-within,
    form[action="/search"]:focus-within,
    input[type="search"]:focus {
        background-color: #FFB7CE !important; /* Rosa Pastel base */
        background: #FFB7CE !important;
        border: 2px solid #FFFFFF !important;
        border-radius: 30px !important;
        color: #FFFFFF !important;
    }
    
    /* Evitamos que el fondo se vuelva negro al escribir */
    #search-input, .search-input, input[type="search"]::-webkit-search-cancel-button {
        background-color: transparent !important;
        color: #FFFFFF !important;
    }

    /* 3. ICONOS DEL MENÚ: Todo en Rosa Pastel (¡Sin volverse negro al presionarlos!) */
    svg, 
    path, 
    faceplate-icon,
    [icon-name="home-outline"], 
    [icon-name="popular-outline"],
    [aria-label*="Inicio"] svg, 
    [aria-label*="Popular"] svg, 
    [aria-label*="Notificaciones"] svg, 
    [aria-label*="Mensajes"] svg,
    shreddit-sidebar-nav svg,
    #expanded-header-avatar,
    [data-testid="profile-icon"],
    /* Forzamos el estado presionado/activo */
    a[aria-current="page"] svg,
    button:active svg,
    a:active svg,
    .is-selected svg {
        fill: #FFB7CE !important; /* Rosa Pastel */
        color: #FFB7CE !important;
    }

    /* 4. PERFIL E INFORMACIÓN DE LA CUENTA */
    #user-drawer,
    [aria-label="User drawer"],
    .text-neutral-content-strong,
    [data-testid="profile-username"],
    shreddit-nav-user-dropdown span {
        color: #FFB7CE !important;
        font-family: 'Georgia', 'Lucida Handwriting', cursive !important;
        font-style: italic !important;
        text-shadow: -1px -1px 0 #db335b, 1px -1px 0 #db335b, -1px 1px 0 #db335b, 1px 1px 0 #db335b !important;
    }

    /* 5. PUBLICACIONES Y COMENTARIOS: Letras Marrón Claro Cursivas */
    h1, h2, h3, p, span, a, shreddit-post, .text-neutral-content, faceplate-number, time, [data-testid="post-title"], .md {
        color: #A0522D !important;
        font-family: 'Georgia', 'Lucida Handwriting', cursive !important;
        font-style: italic !important;
        text-shadow: -1px -1px 0 #FFFFFF, 1px -1px 0 #FFFFFF, -1px 1px 0 #FFFFFF, 1px 1px 0 #FFFFFF !important;
    }
    a:link, a:visited { color: #A0522D !important; }
}
